/// Look up a realm by name, falling back to `fantasy` for an unknown one — matching Go's
/// `GenerateName`, which falls back rather than erroring.
pub const fn realm_by_name(name: &str) -> &'static Realm {
    let mut i = 0;
    while i < REALMS.len() {
        if crate::str_eq_ascii_ci(REALMS[i].name, name) {
            return REALMS[i];
        }
        i += 1;
    }
    &FANTASY
}
